const row = msg.payload;

const Uw = Number(row.wind_speed_2m_mps);
const Lfl = Number(row.flame_length_m);
const Wfb = Number(row.firebreak_width_m);
const tc = Number(row.burn_time_s);

if ([Uw, Lfl, Wfb, tc].some(v => Number.isNaN(v))) {
    node.error("Missing or invalid numeric input", msg);
    return null;
}

const beta_tx =
    -1.8925 +
    (0.055 * Uw) +
    (0.9418 * Lfl) -
    (0.4469 * Wfb) +
    (0.0114 * tc);

const crossing_probability = Math.exp(beta_tx) / (1 + Math.exp(beta_tx));

let risk_level;
if (crossing_probability < 0.25) {
    risk_level = "moderate";
} else if (crossing_probability < 0.35) {
    risk_level = "transition";
} else if (crossing_probability < 0.45) {
    risk_level = "high";
} else {
    risk_level = "severe";
}

const cross_threshold = Number(row.cross_threshold ?? 0.30);
const predicted_crossed_yes_no =
    crossing_probability >= cross_threshold ? "YES" : "NO";

const result = {
    telemetry_observation_id: row.telemetry_observation_id,
    model_run_id: row.model_run_id,
    firebreak_width_m_snapshot: Wfb,
    beta_tx,
    crossing_probability,
    risk_level,
    predicted_crossed_yes_no
};

msg.payload = result;

msg.params = [
    result.telemetry_observation_id,
    result.model_run_id,
    result.firebreak_width_m_snapshot,
    result.beta_tx,
    result.crossing_probability,
    result.risk_level,
    result.predicted_crossed_yes_no
];

return msg;

const engine = global.get("scenarioEngine");
const scenario = global.get("scenarios").brushfireWestline01;
const stateKey = "scenarioState";
const action = msg.action;
let state = flow.get(stateKey);

const createRun = () => {
    const startedAt = new Date().toISOString();
    const seed = Number(msg.seed ?? scenario.defaultSeed);

    return engine.initializeScenario(scenario, {
        runId: `${scenario.scenarioKey}-${Date.now()}`,
        seed,
        startedAt,
    });
};

switch (action) {
    case "start":
        if (state && ["running", "paused"].includes(state.status)) {
            node.warn("A scenario run is already active");
            return null;
        }
        state = createRun();
        break;
    case "reset":
        state = createRun();
        break;
    case "pause":
        if (!state) {
            node.warn("Start a scenario before pausing it");
            return null;
        }
        state = engine.pauseScenario(state);
        break;
    case "resume":
        if (!state) {
            node.warn("Start a scenario before resuming it");
            return null;
        }
        state = engine.resumeScenario(state);
        break;
    case "wind-shift":
        if (!state || state.status === "complete") {
            node.warn("Start an active scenario before triggering an event");
            return null;
        }
        state = engine.applyScenarioEvent(scenario, state, "wind-shift");
        break;
    default:
        node.error(`Unknown scenario control: ${action}`, msg);
        return null;
}

flow.set(stateKey, state);

const color = state.status === "running" ? "green" : "yellow";
node.status({
    fill: color,
    shape: "dot",
    text: `${state.status} | ${state.phase} | tick ${state.tick}`,
});

msg.payload = {
    action,
    runId: state.runId,
    status: state.status,
    phase: state.phase,
    tick: state.tick,
    elapsedSeconds: state.elapsedSeconds,
    firedEventIds: state.firedEventIds,
};

return msg;

const engine = global.get("scenarioEngine");
const scenario = global.get("scenarios").brushfireWestline01;
const stateKey = "scenarioState";
const action = msg.action;
let state = flow.get(stateKey);

if (!state) {
    if (action === "tick") {
        return [null, null];
    }
    node.warn("Start a scenario before advancing it");
    return [null, null];
}

if (action === "tick" && state.status !== "running") {
    return [null, null];
}

if (action === "step") {
    if (state.status !== "paused") {
        node.warn("Step is available only while the scenario is paused");
        return [null, null];
    }
    state = engine.resumeScenario(state);
} else if (action !== "tick") {
    node.error(`Unknown advance action: ${action}`, msg);
    return [null, null];
}

const result = engine.advanceScenario(scenario, state);
let nextState = result.state;

if (action === "step" && nextState.status === "running") {
    nextState = engine.pauseScenario(nextState);
}

flow.set(stateKey, nextState);

const color = nextState.status === "complete" ? "blue" : "green";
node.status({
    fill: color,
    shape: "dot",
    text: `${nextState.status} | ${nextState.phase} | tick ${nextState.tick}`,
});

if (!result.telemetry) {
    return [null, null];
}

const telemetryMessage = {
    ...msg,
    payload: result.telemetry,
};

const outcomeMessage = result.outcome
    ? {
          payload: result.outcome,
          runId: nextState.runId,
          telemetry: result.telemetry,
      }
    : null;

return [telemetryMessage, outcomeMessage];
